    test("subscribe_to_turn (1)", async () => {
        const server = mockServerPool.createServer();
        const client = new TrueForge({ maxRetries: 0, token: "test", baseUrl: server.baseUrl });

        const rawResponseBody =
            'event: \ndata: {"created_at":"created_at","id":"id","mode":"coding","outcome":"applied","reason":"missing_block","summary_chars":1,"thread_id":"thread_id","tokens_after":1.1,"tokens_before":1.1,"type":"agent.context.compaction"}\n\n';

        server
            .mockEndpoint()
            .get("/api/v1/sessions/session_id/turns/turn_id/subscribe")
            .respondWith()
            .statusCode(200)
            .sseBody(rawResponseBody)
            .build();

        const response = await client.sessions.subscribeToTurn("session_id", "turn_id");
        const events: unknown[] = [];
        for await (const event of response) {
            events.push(event);
        }
        expect(events).toEqual([
            {
                createdAt: "created_at",
                id: "id",
                mode: "coding",
                outcome: "applied",
                reason: "missing_block",
                summaryChars: 1,
                threadId: "thread_id",
                tokensAfter: 1.1,
                tokensBefore: 1.1,
                type: "agent.context.compaction",
            },
        ]);
    });

